<?php
class Booking { private $pdo; public function __construct($pdo){$this->pdo=$pdo;} public function allFor($uid=null){$sql='SELECT b.*,j.tanggal,j.jam_mulai,j.studio,f.judul FROM booking b JOIN jadwal j ON j.id=b.jadwal_id JOIN film f ON f.id=j.film_id';$p=[];if($uid!==null){$sql.=' WHERE b.user_id=?';$p[]=$uid;}$sql.=' ORDER BY b.created_at DESC';$s=$this->pdo->prepare($sql);$s->execute($p);return $s->fetchAll();} public function create($uid,$jadwal,$kode,$qty,$total){$s=$this->pdo->prepare('INSERT INTO booking(user_id,jadwal_id,kode_booking,jumlah_kursi,total,status) VALUES(?,?,?,?,?,"aktif")');return $s->execute([$uid,$jadwal,$kode,$qty,$total]);} public function cancel($id,$uid){$s=$this->pdo->prepare('UPDATE booking SET status="dibatalkan" WHERE id=? AND user_id=? AND status="aktif"');return $s->execute([$id,$uid]);}}
?>
